from PIL import Image
img = Image.open('image.png').convert('RGB')
w, h = img.size
bits = ''
for y in range(h):
    for x in range(w):
        for c in img.getpixel((x, y)):
            bits += str(c & 1)
data = bytes(int(bits[i:i+8], 2) for i in range(0, len(bits)//8*8, 8))
print(data.decode('latin-1'))
